// appConfigBackend.ts -- AWS AppConfig Data API backend for the runtime config store
//
// Auto-generated by cruftfree-codegen-typescript. Do not edit manually.
//
// Reads config-store profiles from AWS AppConfig using the AppConfig Data API
// (`StartConfigurationSession` + `GetLatestConfiguration`) via
// `@aws-sdk/client-appconfigdata`. Each config-store profile maps to one
// AppConfig configuration profile under a shared application and environment:
//
// - application  -> AppConfig ApplicationIdentifier      (`marram`)
// - environment  -> AppConfig EnvironmentIdentifier       (`local`)
// - profile name -> AppConfig ConfigurationProfileIdentifier
//
// The AWS region is the deployment region baked into `_bootstrap`; the client signs with the
// platform-delivered role alone (`_runtime/aws-role`). The session token returned
// by `GetLatestConfiguration` is retained per profile so each refresh fetches
// only the delta; an empty `Configuration` payload means "unchanged" and the
// previously decoded values for that profile are returned again.
//
// Content normalization (parity with the Python AppConfig backend):
// - feature-flag content (`{ flagKey: { enabled, ... }, ... }`) is reduced to
//   `flagKey -> enabled` (boolean), dropping per-flag attributes and the
//   `_meta` block that AppConfig adds to feature-flag profiles;
// - freeform JSON (`{ key: value }`) is returned as-is.
// In both cases the client validates and merges the result over the generated
// defaults; secret values are never stored here (secretRef keys carry metadata
// only, resolved by generated secret-manager access code).

import {
  AppConfigDataClient,
  StartConfigurationSessionCommand,
  GetLatestConfigurationCommand,
} from '@aws-sdk/client-appconfigdata';
import { REGION } from "../_bootstrap";
import { awsClient } from "../../_runtime/aws-role";

const APPLICATION_NAME = 'marram';
// Baked at generation time from the resolved deployment -- no environment
// variable reads for the deployment environment at runtime.
const ENVIRONMENT = "local";
const FEATURE_FLAG_META_KEY = '_meta';
const FEATURE_FLAG_ENABLED_KEY = 'enabled';
// AppConfig requires the session poll interval to be at least 15 seconds.
const MIN_POLL_INTERVAL_SECONDS = 15;

export const PROFILE_NAMES = [
  'settings',
] as const;

/** Thrown when AppConfig cannot be reached or returns malformed configuration. */
export class AppConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'AppConfigError';
  }
}

/** Per-profile session state retained across polling refreshes. */
interface ProfileSession {
  token: string;
  values: Record<string, unknown>;
}

/** Read config-store profiles from AWS AppConfig via the AppConfig Data API. */
export class AppConfigBackend {
  private readonly client: AppConfigDataClient;
  private readonly environment: string;
  private readonly sessions = new Map<string, ProfileSession>();

  constructor() {
    if (!REGION) {
      throw new AppConfigError(
        'The AppConfig backend needs a region: generate with a resolved deployment region. ' +
          'The service never falls back to an environment variable.',
      );
    }
    this.client = awsClient(AppConfigDataClient, { region: REGION });
    this.environment = ENVIRONMENT;
  }

  /**
   * Name the AppConfig application/environment this backend reads, for a
   * fail-closed lookup's error message. Both are baked identifiers, never a
   * credential -- the session token this backend holds is deliberately not
   * named here.
   */
  describeSource(): string {
    return `AWS AppConfig application '${APPLICATION_NAME}' environment '${this.environment}'`;
  }

  /**
   * Return decoded scalar values for one profile keyed by config key name.
   *
   * Starts (or resumes) an AppConfig configuration session for the profile and
   * fetches the latest configuration. An empty payload means the configuration
   * is unchanged since the last poll, in which case the previously decoded
   * values are returned. The client falls back to generated defaults for any
   * key absent from the returned mapping.
   */
  async fetchProfile(profile: string): Promise<Record<string, unknown>> {
    const token = await this.resolveToken(profile);

    let response;
    try {
      response = await this.client.send(
        new GetLatestConfigurationCommand({ ConfigurationToken: token }),
      );
    } catch (err) {
      this.sessions.delete(profile);
      throw new AppConfigError(
        `Failed to fetch AppConfig configuration for profile '${profile}' ` +
          `(application '${APPLICATION_NAME}', environment '${this.environment}'): ` +
          `${String(err)}. Verify the AppConfig profile exists and the runtime ` +
          'has appconfig:GetLatestConfiguration permission.',
      );
    }

    const nextToken = response.NextPollConfigurationToken;
    const existing = this.sessions.get(profile);
    const payload = response.Configuration;

    if (payload === undefined || payload.length === 0) {
      // Empty payload => configuration unchanged; reuse the last decoded values.
      const values = existing?.values ?? {};
      if (nextToken !== undefined) {
        this.sessions.set(profile, { token: nextToken, values });
      }
      return { ...values };
    }

    const text = new TextDecoder('utf-8').decode(payload);
    const values = decodeContent(profile, text);
    if (nextToken !== undefined) {
      this.sessions.set(profile, { token: nextToken, values });
    }
    return { ...values };
  }

  private async resolveToken(profile: string): Promise<string> {
    const existing = this.sessions.get(profile);
    if (existing !== undefined) {
      return existing.token;
    }
    let response;
    try {
      response = await this.client.send(
        new StartConfigurationSessionCommand({
          ApplicationIdentifier: APPLICATION_NAME,
          EnvironmentIdentifier: this.environment,
          ConfigurationProfileIdentifier: profile,
          RequiredMinimumPollIntervalInSeconds: MIN_POLL_INTERVAL_SECONDS,
        }),
      );
    } catch (err) {
      throw new AppConfigError(
        `Failed to start an AppConfig session for profile '${profile}' ` +
          `(application '${APPLICATION_NAME}', environment '${this.environment}'): ` +
          `${String(err)}. Verify the AppConfig application, environment, and ` +
          'configuration profile names match the config-store declaration.',
      );
    }
    const token = response.InitialConfigurationToken;
    if (token === undefined) {
      throw new AppConfigError(
        `AppConfig did not return an initial configuration token for profile ` +
          `'${profile}'. Expected StartConfigurationSession to return ` +
          'InitialConfigurationToken.',
      );
    }
    return token;
  }
}

function decodeContent(profile: string, text: string): Record<string, unknown> {
  const trimmed = text.trim();
  if (trimmed === '') {
    return {};
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(trimmed);
  } catch (err) {
    throw new AppConfigError(
      `AppConfig configuration for profile '${profile}' is not valid JSON: ` +
        `${String(err)}. Store config profiles as JSON (freeform document or ` +
        'AppConfig feature-flag content).',
    );
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    throw new AppConfigError(
      `AppConfig configuration for profile '${profile}' must be a JSON object ` +
        `of key -> value; got ${Array.isArray(parsed) ? 'array' : typeof parsed}.`,
    );
  }
  return normalize(parsed as Record<string, unknown>);
}

/**
 * Normalize AppConfig content into the client's key -> scalar contract.
 *
 * Feature-flag content nests each flag under its key as an object carrying at
 * least `enabled`; it is reduced to `flagKey -> enabled` and the AppConfig
 * `_meta` block is dropped. Freeform content is already `key -> scalar` and is
 * returned unchanged.
 */
function normalize(content: Record<string, unknown>): Record<string, unknown> {
  if (!isFeatureFlagContent(content)) {
    return { ...content };
  }
  const values: Record<string, unknown> = {};
  for (const [key, entry] of Object.entries(content)) {
    if (key === FEATURE_FLAG_META_KEY) {
      continue;
    }
    if (isRecord(entry) && FEATURE_FLAG_ENABLED_KEY in entry) {
      values[key] = entry[FEATURE_FLAG_ENABLED_KEY];
    }
  }
  return values;
}

/**
 * Detect AppConfig feature-flag content: every non-`_meta` value is an object
 * exposing an `enabled` member. Freeform documents (scalar values, or objects
 * without `enabled`) are left untouched.
 */
function isFeatureFlagContent(content: Record<string, unknown>): boolean {
  let sawFlag = false;
  for (const [key, entry] of Object.entries(content)) {
    if (key === FEATURE_FLAG_META_KEY) {
      continue;
    }
    if (!isRecord(entry) || !(FEATURE_FLAG_ENABLED_KEY in entry)) {
      return false;
    }
    sawFlag = true;
  }
  return sawFlag;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}
